sect1.programlisting:
use valgrind_requests::{callgrind, valgrind}; // version 1.1.0

assert!(valgrind::running_on_valgrind() != 0);
assert!(valgrind::monitor_command(c"lackey function add target_*"));
assert!(valgrind::monitor_command(c"lackey output region.trace"));
callgrind::start_instrumentation();
// Execute the workload here.
callgrind::stop_instrumentation();
assert!(valgrind::monitor_command(c"lackey output log"));
